import { useCallback, useEffect, useRef, useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { datasetService } from '../../services/datasetService';
import { analysisService } from '../../services/analysisService';
import VerifiedTrendChart from '../../components/analytics/VerifiedTrendChart';
import type { Dataset } from '../../types/datasets';
import type {
  AnalysisSessionDetail,
  AnalysisSessionSummary,
  AnalysisTurn,
  ChartSpec,
  KpiMetrics,
} from '../../types/analysis';

export default function AnalysisPage() {
  const location = useLocation();
  const navigate = useNavigate();
  const initial = location.state as { question?: string; datasetId?: string; sessionId?: string } | null;
  const searchParams = new URLSearchParams(location.search);

  // Core state
  const [datasets, setDatasets] = useState<Dataset[]>([]);
  const [datasetId, setDatasetId] = useState<string>(
    initial?.datasetId ?? searchParams.get('datasetId') ?? searchParams.get('dataset') ?? ''
  );
  const [question, setQuestion] = useState<string>(initial?.question ?? '');
  const [loadingDatasets, setLoadingDatasets] = useState(true);
  const [running, setRunning] = useState(false);
  const [error, setError] = useState<string>('');

  // Persistent Sessions state
  const [sessions, setSessions] = useState<AnalysisSessionSummary[]>([]);
  const [loadingSessions, setLoadingSessions] = useState(false);
  const [sessionSearch, setSessionSearch] = useState<string>('');
  const [activeSessionId, setActiveSessionId] = useState<string | null>(
    initial?.sessionId ?? searchParams.get('session_id') ?? null
  );
  const [activeSession, setActiveSession] = useState<AnalysisSessionDetail | null>(null);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  const requestRef = useRef<AbortController | null>(null);
  const turnsEndRef = useRef<HTMLDivElement | null>(null);

  // 1. Load available datasets
  useEffect(() => {
    let active = true;
    datasetService
      .list()
      .then((items) => {
        if (!active) return;
        setDatasets(items);
        setDatasetId((current) =>
          items.some((d) => d.dataset_id === current) ? current : items[0]?.dataset_id ?? ''
        );
      })
      .catch((e) => {
        if (active) setError(e instanceof Error ? e.message : 'Unable to load datasets.');
      })
      .finally(() => {
        if (active) setLoadingDatasets(false);
      });
    return () => {
      active = false;
    };
  }, []);

  // 2. Load persistent session history
  const loadSessions = useCallback(async () => {
    setLoadingSessions(true);
    try {
      const list = await analysisService.listSessions(null, sessionSearch);
      setSessions(list);
    } catch {
      // Non-blocking error for session list
    } finally {
      setLoadingSessions(false);
    }
  }, [sessionSearch]);

  useEffect(() => {
    void loadSessions();
  }, [loadSessions]);

  // 3. Load active session details when activeSessionId changes
  useEffect(() => {
    if (!activeSessionId) {
      setActiveSession(null);
      return;
    }

    let active = true;
    analysisService
      .getSession(activeSessionId)
      .then((detail) => {
        if (!active) return;
        setActiveSession(detail);
        if (detail.dataset_id && (!datasetId || datasetId !== detail.dataset_id)) {
          setDatasetId(detail.dataset_id);
        }
      })
      .catch((err) => {
        if (active) {
          setError(err instanceof Error ? err.message : 'Failed to restore analysis session.');
          setActiveSession(null);
        }
      });

    return () => {
      active = false;
    };
  }, [activeSessionId]);

  // Abort on unmount
  useEffect(() => () => requestRef.current?.abort(), []);

  // Auto-scroll to bottom of conversation
  useEffect(() => {
    turnsEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [activeSession?.turns]);

  // Handle switching or creating new session
  function handleStartNewSession() {
    setActiveSessionId(null);
    setActiveSession(null);
    setQuestion('');
    setError('');
    navigate('/analysis', { replace: true });
  }

  function handleSelectSession(sid: string) {
    if (sid === activeSessionId) return;
    setActiveSessionId(sid);
    setError('');
    navigate(`/analysis?session_id=${encodeURIComponent(sid)}`, { replace: true });
  }

  async function handleDeleteSession(e: React.MouseEvent, sid: string) {
    e.stopPropagation();
    if (!window.confirm('Are you sure you want to delete this analysis session?')) return;
    try {
      await analysisService.deleteSession(sid);
      if (activeSessionId === sid) {
        handleStartNewSession();
      }
      await loadSessions();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not delete session.');
    }
  }

  // Execute or follow-up analysis
  async function handleSubmitAnalysis(e?: React.FormEvent) {
    if (e) e.preventDefault();
    const promptText = question.trim();
    if (!promptText || !datasetId || running) return;

    const controller = new AbortController();
    requestRef.current = controller;
    setRunning(true);
    setError('');

    try {
      const response = await analysisService.ask({
        message: promptText,
        datasetId,
        sessionId: activeSessionId,
        signal: controller.signal,
      });

      if (controller.signal.aborted) return;

      const sid = response.session_id || activeSessionId;
      if (sid && sid !== activeSessionId) {
        setActiveSessionId(sid);
        navigate(`/analysis?session_id=${encodeURIComponent(sid)}`, { replace: true });
      }

      setQuestion('');
      // Reload active session turns from server for persistent single source of truth
      if (sid) {
        const updated = await analysisService.getSession(sid);
        setActiveSession(updated);
      }
      await loadSessions();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Analysis could not complete.');
    } finally {
      setRunning(false);
    }
  }

  const selectedDataset = datasets.find((d) => d.dataset_id === datasetId);

  return (
    <div className="ws-page" style={{ padding: '24px 32px', maxWidth: 1600 }}>
      <Link to="/verified-learning" className="btn btn--ghost">Open verified analysis and learning evidence</Link>
      {/* Editorial Hero Header */}
      <header className="analysis-hero" style={{ marginBottom: 20 }}>
        <div>
          <p className="eyebrow">AI ANALYSIS & PERSISTENT CONVERSATIONAL WORKSPACE</p>
          <h1 style={{ margin: '14px 0' }}>
            Good questions.<br />
            <em>Verifiable answers.</em>
          </h1>
          <p style={{ margin: 0 }}>
            Every calculation, chart, and citation is saved into your persistent workspace history.
          </p>
        </div>
        <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
          <button
            type="button"
            className="btn btn--primary"
            onClick={handleStartNewSession}
            style={{ fontWeight: 600 }}
          >
            + New Analysis
          </button>
          <Link className="editorial-link" to="/datasets/upload">
            Add dataset ↗
          </Link>
        </div>
      </header>

      {error && (
        <div
          role="alert"
          style={{
            padding: '14px 18px',
            borderRadius: 10,
            background: 'rgba(239, 68, 68, 0.12)',
            border: '1px solid rgba(239, 68, 68, 0.3)',
            color: '#f87171',
            marginBottom: 20,
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}
        >
          <span>{error}</span>
          <button
            className="btn btn--ghost btn--sm"
            onClick={() => setError('')}
            style={{ color: '#f87171' }}
          >
            Dismiss
          </button>
        </div>
      )}

      {loadingDatasets ? (
        <p role="status" style={{ color: 'var(--text-muted)' }}>
          Loading analytical workspace…
        </p>
      ) : datasets.length === 0 ? (
        <section className="dataset-empty surface-panel" style={{ textAlign: 'center', padding: 48 }}>
          <h2>No datasets uploaded yet.</h2>
          <p style={{ color: 'var(--text-muted)' }}>
            Upload your Excel or CSV dataset to start asking analytical questions.
          </p>
          <Link to="/datasets/upload" className="btn btn--primary" style={{ marginTop: 16 }}>
            Upload dataset
          </Link>
        </section>
      ) : (
        /* Workspace Main Layout: Sidebar + Main Stage */
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: sidebarCollapsed ? '48px minmax(0, 1fr)' : '300px minmax(0, 1fr)',
            gap: 24,
            transition: 'grid-template-columns 0.2s ease',
          }}
        >
          {/* ================================================================ */}
          {/* LEFT: COLLAPSIBLE SESSION HISTORY PANEL                         */}
          {/* ================================================================ */}
          <aside
            className="surface-panel"
            style={{
              padding: sidebarCollapsed ? '16px 8px' : '20px',
              display: 'flex',
              flexDirection: 'column',
              gap: 16,
              height: 'fit-content',
              maxHeight: 'calc(100vh - 160px)',
              overflowY: 'auto',
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              {!sidebarCollapsed && (
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <span style={{ fontSize: 13, fontWeight: 700, letterSpacing: '0.05em' }}>
                    SESSIONS
                  </span>
                  <span
                    style={{
                      fontSize: 11,
                      padding: '2px 6px',
                      borderRadius: 12,
                      background: 'var(--surface-raised)',
                      color: 'var(--text-muted)',
                    }}
                  >
                    {sessions.length}
                  </span>
                </div>
              )}
              <button
                type="button"
                className="btn btn--ghost btn--sm"
                onClick={() => setSidebarCollapsed(!sidebarCollapsed)}
                title={sidebarCollapsed ? 'Expand history' : 'Collapse history'}
                style={{ padding: '4px 8px' }}
              >
                {sidebarCollapsed ? '▶' : '◀'}
              </button>
            </div>

            {!sidebarCollapsed && (
              <>
                <button
                  type="button"
                  className="btn btn--secondary"
                  onClick={handleStartNewSession}
                  style={{ width: '100%', justifyContent: 'center' }}
                >
                  + New Analysis
                </button>

                <input
                  type="search"
                  placeholder="Search previous questions…"
                  value={sessionSearch}
                  onChange={(e) => setSessionSearch(e.target.value)}
                  style={{
                    padding: '8px 12px',
                    borderRadius: 8,
                    border: '1px solid var(--border)',
                    background: 'var(--surface-raised)',
                    color: 'var(--text-h)',
                    fontSize: 13,
                    width: '100%',
                    boxSizing: 'border-box',
                  }}
                />

                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {loadingSessions && sessions.length === 0 ? (
                    <p style={{ fontSize: 12, color: 'var(--text-muted)' }}>Loading history…</p>
                  ) : sessions.length === 0 ? (
                    <p style={{ fontSize: 12, color: 'var(--text-muted)', textAlign: 'center', padding: '16px 0' }}>
                      No previous sessions.
                    </p>
                  ) : (
                    sessions.map((sess) => {
                      const isActive = sess.session_id === activeSessionId;
                      return (
                        <div
                          key={sess.session_id}
                          onClick={() => handleSelectSession(sess.session_id)}
                          style={{
                            padding: '12px',
                            borderRadius: 10,
                            border: isActive ? '1px solid var(--accent)' : '1px solid var(--border)',
                            background: isActive ? 'var(--accent-bg)' : 'var(--surface-raised)',
                            cursor: 'pointer',
                            display: 'flex',
                            flexDirection: 'column',
                            gap: 6,
                            transition: 'all 0.15s ease',
                          }}
                        >
                          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                            <span
                              style={{
                                fontSize: 13,
                                fontWeight: 600,
                                color: isActive ? 'var(--text-h)' : 'var(--text)',
                                lineHeight: 1.3,
                                wordBreak: 'break-word',
                              }}
                            >
                              {sess.title || 'Untitled Analysis'}
                            </span>
                            <button
                              type="button"
                              onClick={(e) => handleDeleteSession(e, sess.session_id)}
                              title="Delete session"
                              style={{
                                background: 'transparent',
                                border: 'none',
                                color: 'var(--text-muted)',
                                cursor: 'pointer',
                                padding: '2px 4px',
                                fontSize: 12,
                                opacity: 0.6,
                              }}
                              onMouseEnter={(e) => ((e.target as HTMLElement).style.opacity = '1')}
                              onMouseLeave={(e) => ((e.target as HTMLElement).style.opacity = '0.6')}
                            >
                              ✕
                            </button>
                          </div>

                          <div
                            style={{
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'space-between',
                              fontSize: 11,
                              color: 'var(--text-muted)',
                            }}
                          >
                            <span>{sess.dataset_name || 'Dataset'}</span>
                            <span>{sess.turn_count} {sess.turn_count === 1 ? 'turn' : 'turns'}</span>
                          </div>
                        </div>
                      );
                    })
                  )}
                </div>
              </>
            )}
          </aside>

          {/* ================================================================ */}
          {/* MAIN AREA: ACTIVE SESSION CONVERSATION & ANALYTICAL TURNS       */}
          {/* ================================================================ */}
          <main style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
            {/* Session Status Header */}
            <div
              className="surface-panel"
              style={{
                padding: '16px 20px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                flexWrap: 'wrap',
                gap: 16,
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-muted)' }}>
                  ACTIVE DATASET:
                </span>
                <select
                  id="analysis-dataset"
                  value={datasetId}
                  disabled={running}
                  onChange={(e) => setDatasetId(e.target.value)}
                  style={{
                    padding: '8px 12px',
                    borderRadius: 8,
                    border: '1px solid var(--border)',
                    background: 'var(--surface-raised)',
                    color: 'var(--text-h)',
                    fontSize: 13,
                    minWidth: 220,
                  }}
                >
                  {datasets.map((d) => (
                    <option key={d.dataset_id} value={d.dataset_id}>
                      {d.filename} {d.row_count ? `(${d.row_count.toLocaleString()} rows)` : ''}
                    </option>
                  ))}
                </select>
                {selectedDataset && (
                  <span
                    style={{
                      fontSize: 11,
                      padding: '4px 8px',
                      borderRadius: 6,
                      background: 'rgba(200, 253, 57, 0.1)',
                      color: 'var(--brand-lime)',
                      border: '1px solid rgba(200, 253, 57, 0.25)',
                    }}
                  >
                    Verified Schema Pinning
                  </span>
                )}
              </div>

              {activeSession && (
                <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                  <span style={{ fontSize: 13, color: 'var(--text-muted)' }}>
                    Session: <strong style={{ color: 'var(--text-h)' }}>{activeSession.title}</strong>
                  </span>
                  <Link
                    to="/reports"
                    className="btn btn--ghost btn--sm"
                    style={{ textDecoration: 'none', fontSize: 12 }}
                  >
                    View in Reports ↗
                  </Link>
                </div>
              )}
            </div>

            {/* Turn History or Empty Session Prompt */}
            {activeSession && activeSession.turns.length > 0 ? (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
                {activeSession.turns.map((turn, index) => (
                  <TurnCard
                    key={turn.turn_id || index}
                    turn={turn}
                    datasetName={selectedDataset?.filename || activeSession.dataset_name || 'Dataset'}
                    sessionId={activeSession.session_id}
                  />
                ))}
                <div ref={turnsEndRef} />
              </div>
            ) : (
              <div
                className="surface-panel"
                style={{
                  padding: 40,
                  textAlign: 'center',
                  background: 'var(--surface)',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: 12,
                }}
              >
                <div
                  style={{
                    width: 52,
                    height: 52,
                    borderRadius: 26,
                    background: 'rgba(200, 253, 57, 0.12)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: 'var(--brand-lime)',
                    fontSize: 24,
                  }}
                >
                  ⚡
                </div>
                <h2 style={{ margin: '8px 0 4px', fontSize: 20 }}>Ask the AI Data Analyst</h2>
                <p style={{ color: 'var(--text-muted)', maxWidth: 520, margin: 0, fontSize: 14 }}>
                  Submit an analytical question or request a calculation. Results, charts, tables, and KPIs
                  will be saved into this session automatically.
                </p>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 12, justifyContent: 'center' }}>
                  {[
                    'Summarize the numeric measures',
                    'Total revenue by company_name',
                    'Which entity has the highest observation?',
                    'Compare top 2 entities',
                  ].map((quick) => (
                    <button
                      key={quick}
                      type="button"
                      className="btn btn--ghost btn--sm"
                      onClick={() => setQuestion(quick)}
                      style={{ fontSize: 12 }}
                    >
                      {quick}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Input Composer / Follow-up Bar */}
            <form
              onSubmit={handleSubmitAnalysis}
              className="surface-panel"
              style={{
                padding: '18px 20px',
                display: 'flex',
                flexDirection: 'column',
                gap: 12,
                position: 'sticky',
                bottom: 20,
                zIndex: 10,
                boxShadow: '0 8px 32px rgba(0,0,0,0.25)',
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <label
                  htmlFor="analysis-question"
                  style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-muted)', letterSpacing: '0.04em' }}
                >
                  {activeSession && activeSession.turns.length > 0
                    ? 'ASK A FOLLOW-UP QUESTION'
                    : 'NEW ANALYTICAL QUESTION'}
                </label>
                {activeSession && (
                  <span style={{ fontSize: 11, color: 'var(--brand-lime)' }}>
                    ● Maintaining context for {activeSession.title}
                  </span>
                )}
              </div>

              <textarea
                id="analysis-question"
                rows={2}
                maxLength={2000}
                required
                value={question}
                disabled={running}
                onChange={(e) => setQuestion(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    void handleSubmitAnalysis();
                  }
                }}
                placeholder={
                  activeSession && activeSession.turns.length > 0
                    ? 'e.g. Which company has the highest profit? Compare it with the second-highest.'
                    : 'e.g. Analyze companies and their profits across the population'
                }
                style={{
                  width: '100%',
                  padding: '12px 14px',
                  borderRadius: 8,
                  border: '1px solid var(--border)',
                  background: 'var(--surface-raised)',
                  color: 'var(--text-h)',
                  fontSize: 14,
                  resize: 'none',
                  boxSizing: 'border-box',
                }}
              />

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>
                  Press <kbd style={{ padding: '2px 5px', borderRadius: 4, background: 'var(--code-bg)' }}>Enter ↵</kbd> to execute
                </span>

                <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                  {running && (
                    <button
                      type="button"
                      className="btn btn--ghost btn--sm"
                      onClick={() => requestRef.current?.abort()}
                    >
                      Cancel
                    </button>
                  )}
                  <button
                    type="submit"
                    className="btn btn--primary"
                    disabled={running || !question.trim()}
                    style={{ minWidth: 130, justifyContent: 'center' }}
                  >
                    {running ? 'Analyzing…' : activeSession ? 'Send Follow-up' : 'Run Analysis'}
                  </button>
                </div>
              </div>
            </form>
          </main>
        </div>
      )}
    </div>
  );
}

// ==============================================================================
// TURN CARD COMPONENT: Shows question + verified answer + KPIs + Chart + Table
// ==============================================================================
function TurnCard({
  turn,
  datasetName,
  sessionId,
}: {
  turn: AnalysisTurn;
  datasetName: string;
  sessionId: string;
}) {
  const navigate = useNavigate();
  const columns = Array.from(new Set((turn.data || []).flatMap((row) => Object.keys(row))));

  function handleOpenReportStudio() {
    navigate('/reports', {
      state: {
        selectedRunId: turn.run_id,
        sessionId,
        title: turn.question,
      },
    });
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      {/* 1. User Question Prompt */}
      <div
        style={{
          display: 'flex',
          alignItems: 'flex-start',
          gap: 12,
          padding: '14px 18px',
          borderRadius: 12,
          background: 'var(--surface-raised)',
          border: '1px solid var(--border)',
          alignSelf: 'flex-start',
          maxWidth: '85%',
        }}
      >
        <div
          style={{
            width: 28,
            height: 28,
            borderRadius: 14,
            background: 'var(--accent-bg)',
            color: 'var(--accent)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: 12,
            fontWeight: 700,
            flexShrink: 0,
          }}
        >
          Q
        </div>
        <div>
          <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-h)' }}>
            {turn.question}
          </div>
          {turn.asked_at && (
            <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 4 }}>
              {new Date(turn.asked_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </div>
          )}
        </div>
      </div>

      {/* 2. AI Analyst Answer & Verified Artifacts */}
      <div
        className="surface-panel"
        style={{
          padding: '24px',
          borderLeft: '4px solid var(--brand-lime)',
          display: 'flex',
          flexDirection: 'column',
          gap: 18,
        }}
      >
        {/* Header: Status, Execution time, Source */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 10 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <span
              style={{
                fontSize: 11,
                fontWeight: 700,
                padding: '3px 8px',
                borderRadius: 4,
                background: turn.status === 'clarification_required' ? 'rgba(245, 158, 11, 0.2)' : 'rgba(16, 185, 129, 0.2)',
                color: turn.status === 'clarification_required' ? '#f59e0b' : '#10b981',
              }}
            >
              {turn.status === 'clarification_required' ? 'CLARIFICATION NEEDED' : 'CALCULATED & VERIFIED'}
            </span>
            <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>
              Source: <strong>{datasetName}</strong> · Latency: {turn.execution_time.toFixed(2)}s
            </span>
          </div>

          {turn.run_id && turn.status !== 'clarification_required' && (
            <button
              type="button"
              className="btn btn--secondary btn--sm"
              onClick={handleOpenReportStudio}
              title="Generate a formal PDF report from this verified analysis"
            >
              Generate Detailed Report 📄
            </button>
          )}
        </div>

        {/* Primary Answer */}
        <div>
          <h3 style={{ margin: '0 0 8px', fontSize: 18, color: 'var(--text-h)', lineHeight: 1.4 }}>
            {turn.answer}
          </h3>
          {turn.explanation && (
            <p style={{ margin: 0, color: 'var(--text)', fontSize: 14, lineHeight: 1.6 }}>
              {turn.explanation}
            </p>
          )}
        </div>

        {/* Population KPIs */}
        {turn.kpis && Object.keys(turn.kpis).length > 0 && (
          <KpiGrid kpis={turn.kpis} />
        )}

        {/* Chart Visualization */}
        {turn.chart && turn.chart.points && turn.chart.points.length > 0 && (
          turn.chart.chart_type === 'line' ? <VerifiedTrendChart chart={turn.chart} /> : <BarChartRenderer chart={turn.chart} />
        )}

        {/* Data Table */}
        {turn.data && turn.data.length > 0 && (
          <div style={{ overflowX: 'auto' }}>
            <table
              className="dataset-table"
              style={{
                width: '100%',
                fontSize: 13,
                borderCollapse: 'collapse',
                textAlign: 'left',
              }}
            >
              <thead>
                <tr style={{ borderBottom: '1px solid var(--border)' }}>
                  {columns.map((c) => (
                    <th key={c} style={{ padding: '8px 12px', color: 'var(--text-muted)', fontWeight: 600 }}>
                      {c}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {turn.data.slice(0, 20).map((row, rIdx) => (
                  <tr key={rIdx} style={{ borderBottom: '1px solid var(--border)' }}>
                    {columns.map((c) => (
                      <td key={c} style={{ padding: '8px 12px' }}>
                        {row[c] == null ? '—' : String(row[c])}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
            {turn.data.length > 20 && (
              <div style={{ fontSize: 11, color: 'var(--text-muted)', padding: '6px 12px' }}>
                Showing 20 of {turn.data.length} observations
              </div>
            )}
          </div>
        )}

        {/* Verified RAG Citations */}
        {turn.citations && turn.citations.length > 0 && (
          <div style={{ borderTop: '1px solid var(--border)', paddingTop: 14 }}>
            <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-muted)', display: 'block', marginBottom: 8 }}>
              RETRIEVED DOCUMENT EVIDENCE ({turn.citations.length} CITATIONS)
            </span>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 10 }}>
              {turn.citations.map((cite, cIdx) => (
                <div
                  key={cIdx}
                  style={{
                    padding: '10px 14px',
                    borderRadius: 8,
                    background: 'var(--surface-raised)',
                    border: '1px solid var(--border)',
                    fontSize: 12,
                  }}
                >
                  <strong style={{ color: 'var(--brand-lime)', display: 'block', marginBottom: 4 }}>
                    {cite.title || cite.doc_id || `Source #${cIdx + 1}`}
                  </strong>
                  <p style={{ margin: 0, color: 'var(--text)', fontStyle: 'italic', opacity: 0.9 }}>
                    "{cite.snippet ? cite.snippet.slice(0, 160) + '…' : 'Document passage reference'}"
                  </p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Actionable Recommendations */}
        {turn.actionable && turn.actionable.length > 0 && (
          <div style={{ borderTop: '1px solid var(--border)', paddingTop: 12 }}>
            <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-muted)' }}>
              SUGGESTED NEXT ACTIONS:
            </span>
            <ul style={{ margin: '6px 0 0', paddingLeft: 20, fontSize: 13, color: 'var(--text)' }}>
              {turn.actionable.map((item, iIdx) => (
                <li key={iIdx} style={{ margin: '3px 0' }}>{item}</li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  );
}

// ==============================================================================
// KPI GRID COMPONENT
// ==============================================================================
function KpiGrid({ kpis }: { kpis: KpiMetrics }) {
  const fields = ['total', 'mean', 'median', 'min', 'max', 'count'];
  const present = fields.filter((f) => kpis[f] !== undefined);
  if (present.length === 0) return null;

  return (
    <div
      style={{
        display: 'grid',
        gridTemplateColumns: `repeat(auto-fit, minmax(110px, 1fr))`,
        gap: 12,
      }}
    >
      {present.map((key) => {
        const val = kpis[key];
        const displayVal =
          typeof val === 'number'
            ? val % 1 !== 0
              ? val.toLocaleString(undefined, { maximumFractionDigits: 2 })
              : val.toLocaleString()
            : String(val);

        return (
          <div
            key={key}
            style={{
              padding: '12px 14px',
              borderRadius: 10,
              background: 'var(--surface-raised)',
              border: '1px solid var(--border)',
            }}
          >
            <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase' }}>
              {key}
            </div>
            <div style={{ fontSize: 20, fontWeight: 700, color: 'var(--text-h)', marginTop: 4 }}>
              {displayVal}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ==============================================================================
// BAR CHART RENDERER COMPONENT: Clean, robust, verified visualization preview
// ==============================================================================
function BarChartRenderer({ chart }: { chart: ChartSpec }) {
  const maxVal = Math.max(...chart.points.map((p) => p.value), 1);

  return (
    <div
      style={{
        padding: '16px 20px',
        borderRadius: 12,
        background: 'var(--surface-raised)',
        border: '1px solid var(--border)',
        display: 'flex',
        flexDirection: 'column',
        gap: 14,
      }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-h)' }}>
          {chart.chart_label || `${chart.y_field} by ${chart.x_field}`}
        </span>
        <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>
          Verified Aggregate Series
        </span>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        {chart.points.map((pt, idx) => {
          const pct = Math.max(0, Math.min(100, (pt.value / maxVal) * 100));
          return (
            <div key={idx} style={{ display: 'grid', gridTemplateColumns: '160px minmax(0, 1fr) 90px', gap: 12, alignItems: 'center' }}>
              <span
                style={{
                  fontSize: 12,
                  fontWeight: 500,
                  color: 'var(--text)',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                }}
                title={pt.label}
              >
                {pt.label}
              </span>
              <div
                style={{
                  height: 18,
                  borderRadius: 4,
                  background: 'var(--code-bg)',
                  overflow: 'hidden',
                  position: 'relative',
                }}
              >
                <div
                  style={{
                    height: '100%',
                    width: `${pct}%`,
                    background: 'var(--brand-lime)',
                    borderRadius: 4,
                    transition: 'width 0.4s ease',
                  }}
                />
              </div>
              <span style={{ fontSize: 12, fontWeight: 600, color: 'var(--text-h)', textAlign: 'right' }}>
                {pt.value.toLocaleString(undefined, { maximumFractionDigits: 2 })}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Database, FileUp, Server, CheckCircle2, AlertCircle, Loader2, X, Trash2, RefreshCw } from 'lucide-react';
import { connectionService, type DatabaseConnection, type ConnectionTestResult } from '../../services/connectionService';

export default function ConnectionsPage() {
  const [activeModal, setActiveModal] = useState<'postgresql' | 'mysql' | null>(null);
  const [connName, setConnName] = useState('');
  const [host, setHost] = useState('localhost');
  const [port, setPort] = useState(5432);
  const [database, setDatabase] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [schemaName, setSchemaName] = useState('public');

  const [testing, setTesting] = useState(false);
  const [saving, setSaving] = useState(false);
  const [testResult, setTestResult] = useState<ConnectionTestResult | null>(null);
  const [formError, setFormError] = useState<string | null>(null);
  const [savedConnections, setSavedConnections] = useState<DatabaseConnection[]>([]);
  const [loadingList, setLoadingList] = useState(false);

  // Default workspace ID
  const workspaceId = '00000000-0000-0000-0000-000000000000';

  useEffect(() => {
    loadConnections();
  }, []);

  async function loadConnections() {
    setLoadingList(true);
    try {
      const list = await connectionService.listConnections(workspaceId);
      setSavedConnections(Array.isArray(list) ? list : []);
    } catch {
      // If workspace does not exist yet or unauthenticated in dev, keep empty list
      setSavedConnections([]);
    } finally {
      setLoadingList(false);
    }
  }

  function openModal(type: 'postgresql' | 'mysql') {
    setActiveModal(type);
    setConnName(type === 'postgresql' ? 'Production Postgres' : 'Main MySQL');
    setHost('localhost');
    setPort(type === 'postgresql' ? 5432 : 3306);
    setDatabase('');
    setUsername(type === 'postgresql' ? 'postgres' : 'root');
    setPassword('');
    setSchemaName('public');
    setTestResult(null);
    setFormError(null);
  }

  function closeModal() {
    setActiveModal(null);
    setTestResult(null);
    setFormError(null);
  }

  async function handleTest() {
    if (!activeModal) return;
    if (!host || !database || !username) {
      setFormError('Please enter Host, Database name, and Username.');
      return;
    }
    setTesting(true);
    setFormError(null);
    setTestResult(null);

    try {
      const res = await connectionService.testConnection({
        connector_type: activeModal,
        host,
        port: Number(port),
        database,
        username,
        password,
        schema_name: activeModal === 'postgresql' ? schemaName : undefined,
      });
      setTestResult(res);
    } catch (err: any) {
      const msg = err.response?.data?.detail?.message || err.response?.data?.detail || err.message || 'Connection test failed';
      setFormError(typeof msg === 'string' ? msg : JSON.stringify(msg));
    } finally {
      setTesting(false);
    }
  }

  async function handleSave() {
    if (!activeModal) return;
    if (!connName.trim()) {
      setFormError('Please enter a connection name.');
      return;
    }
    setSaving(true);
    setFormError(null);

    try {
      await connectionService.saveConnection({
        workspace_id: workspaceId,
        connector_name: connName.trim(),
        connector_type: activeModal,
        host,
        port: Number(port),
        database,
        username,
        password,
        schema_name: activeModal === 'postgresql' ? schemaName : undefined,
      });
      closeModal();
      void loadConnections();
    } catch (err: any) {
      const msg = err.response?.data?.detail || err.message || 'Failed to save connection';
      setFormError(typeof msg === 'string' ? msg : JSON.stringify(msg));
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete(connId: string) {
    try {
      await connectionService.deleteConnection(connId, workspaceId);
      setSavedConnections(prev => prev.filter(c => c.id !== connId));
    } catch (err) {
      console.error('Delete connection error:', err);
    }
  }

  return (
    <div className="ws-page">
      <header className="editorial-heading">
        <p className="eyebrow">DATA MANAGEMENT / CONNECTIONS</p>
        <h1 className="ws-page-heading">Bring your data together.</h1>
        <p className="ws-page-sub">Connect directly to your relational databases or upload structured datasets.</p>
      </header>

      <div className="connector-grid">
        <section className="surface-panel">
          <FileUp size={30} />
          <h2>File upload</h2>
          <p>Import CSV, XLSX, TSV, JSON, JSONL, Parquet, or documents and inspect schema and quality.</p>
          <span className="capability-badge">Available</span>
          <br /><br />
          <Link className="reports-btn-secondary" to="/datasets/upload">Upload dataset →</Link>
        </section>

        <section className="surface-panel">
          <Database size={30} />
          <h2>PostgreSQL</h2>
          <p>Connect to an external PostgreSQL database with table discovery and read-only schema inspection.</p>
          <span className="capability-badge" style={{ background: '#22c55e', color: '#fff' }}>Supported</span>
          <br /><br />
          <button className="reports-btn-secondary" onClick={() => openModal('postgresql')}>
            Configure connection →
          </button>
        </section>

        <section className="surface-panel">
          <Server size={30} />
          <h2>MySQL</h2>
          <p>Connect to an external MySQL instance to synchronize schemas and query permitted tables.</p>
          <span className="capability-badge" style={{ background: '#22c55e', color: '#fff' }}>Supported</span>
          <br /><br />
          <button className="reports-btn-secondary" onClick={() => openModal('mysql')}>
            Configure connection →
          </button>
        </section>
      </div>

      {/* Configured Connections List */}
      <section className="surface-panel" style={{ marginTop: 24, padding: 24 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <div>
            <p className="eyebrow">ACTIVE DATA SOURCES</p>
            <h2 style={{ fontSize: 20, margin: '4px 0' }}>Configured Database Connections</h2>
          </div>
          <button className="reports-btn-secondary" onClick={loadConnections} disabled={loadingList}>
            <RefreshCw size={14} className={loadingList ? 'spin' : ''} /> Refresh
          </button>
        </div>

        {savedConnections.length === 0 ? (
          <p className="source-note" style={{ margin: 0 }}>
            No external database connections configured yet. Click "Configure connection" above to link a PostgreSQL or MySQL database.
          </p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {savedConnections.map(c => (
              <div
                key={c.id}
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  padding: '14px 18px',
                  background: 'var(--surface-raised, #172015)',
                  borderRadius: 10,
                  border: '1px solid var(--border)',
                }}
              >
                <div>
                  <strong style={{ fontSize: 16, color: 'var(--text-h)' }}>{c.connector_name}</strong>
                  <span style={{ marginLeft: 10, fontSize: 12, padding: '2px 8px', borderRadius: 4, background: '#22c55e22', color: '#22c55e' }}>
                    {c.connector_subtype.toUpperCase()} · {c.status}
                  </span>
                  <p style={{ margin: '4px 0 0', fontSize: 13, color: 'var(--text-muted)' }}>
                    Host: {c.config.host}:{c.config.port} | Database: {c.config.database} | User: {c.config.username}
                  </p>
                </div>
                <button
                  className="reports-btn-secondary"
                  style={{ color: '#ef4444', borderColor: '#ef444444' }}
                  onClick={() => handleDelete(c.id)}
                >
                  <Trash2 size={14} /> Disconnect
                </button>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Connection Modal */}
      {activeModal && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            backgroundColor: 'rgba(0,0,0,0.7)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000,
            padding: 20,
          }}
        >
          <div
            style={{
              background: '#151b17',
              border: '1px solid #2d3e30',
              borderRadius: 16,
              maxWidth: 540,
              width: '100%',
              padding: 28,
              boxShadow: '0 20px 40px rgba(0,0,0,0.5)',
              color: '#cbd5c7',
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <div>
                <p className="eyebrow" style={{ color: '#c8fd39' }}>EXTERNAL DATA CONNECTOR</p>
                <h2 style={{ color: '#fff', margin: 0, fontSize: 22 }}>
                  Configure {activeModal === 'postgresql' ? 'PostgreSQL' : 'MySQL'} Source
                </h2>
              </div>
              <button
                onClick={closeModal}
                style={{ background: 'transparent', border: 'none', color: '#888', cursor: 'pointer' }}
              >
                <X size={20} />
              </button>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
              <div style={{ gridColumn: 'span 2' }}>
                <label style={{ display: 'block', fontSize: 12, marginBottom: 4 }}>Connection Name</label>
                <input
                  type="text"
                  value={connName}
                  onChange={e => setConnName(e.target.value)}
                  style={{ width: '100%', padding: '10px 12px', background: '#1c241e', border: '1px solid #334435', borderRadius: 8, color: '#fff' }}
                />
              </div>

              <div>
                <label style={{ display: 'block', fontSize: 12, marginBottom: 4 }}>Host / IP</label>
                <input
                  type="text"
                  value={host}
                  onChange={e => setHost(e.target.value)}
                  style={{ width: '100%', padding: '10px 12px', background: '#1c241e', border: '1px solid #334435', borderRadius: 8, color: '#fff' }}
                />
              </div>

              <div>
                <label style={{ display: 'block', fontSize: 12, marginBottom: 4 }}>Port</label>
                <input
                  type="number"
                  value={port}
                  onChange={e => setPort(Number(e.target.value))}
                  style={{ width: '100%', padding: '10px 12px', background: '#1c241e', border: '1px solid #334435', borderRadius: 8, color: '#fff' }}
                />
              </div>

              <div>
                <label style={{ display: 'block', fontSize: 12, marginBottom: 4 }}>Database Name</label>
                <input
                  type="text"
                  value={database}
                  onChange={e => setDatabase(e.target.value)}
                  placeholder="e.g. analytics_db"
                  style={{ width: '100%', padding: '10px 12px', background: '#1c241e', border: '1px solid #334435', borderRadius: 8, color: '#fff' }}
                />
              </div>

              <div>
                <label style={{ display: 'block', fontSize: 12, marginBottom: 4 }}>Username</label>
                <input
                  type="text"
                  value={username}
                  onChange={e => setUsername(e.target.value)}
                  style={{ width: '100%', padding: '10px 12px', background: '#1c241e', border: '1px solid #334435', borderRadius: 8, color: '#fff' }}
                />
              </div>

              <div style={{ gridColumn: activeModal === 'postgresql' ? 'span 1' : 'span 2' }}>
                <label style={{ display: 'block', fontSize: 12, marginBottom: 4 }}>Password</label>
                <input
                  type="password"
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="••••••••"
                  style={{ width: '100%', padding: '10px 12px', background: '#1c241e', border: '1px solid #334435', borderRadius: 8, color: '#fff' }}
                />
              </div>

              {activeModal === 'postgresql' && (
                <div>
                  <label style={{ display: 'block', fontSize: 12, marginBottom: 4 }}>Schema Name</label>
                  <input
                    type="text"
                    value={schemaName}
                    onChange={e => setSchemaName(e.target.value)}
                    placeholder="public"
                    style={{ width: '100%', padding: '10px 12px', background: '#1c241e', border: '1px solid #334435', borderRadius: 8, color: '#fff' }}
                  />
                </div>
              )}
            </div>

            {formError && (
              <div style={{ marginTop: 16, padding: '10px 14px', background: '#451a1a', border: '1px solid #ef4444', borderRadius: 8, color: '#fca5a5', fontSize: 13, display: 'flex', alignItems: 'center', gap: 8 }}>
                <AlertCircle size={16} />
                <span>{formError}</span>
              </div>
            )}

            {testResult && (
              <div style={{ marginTop: 16, padding: '12px 14px', background: '#14331e', border: '1px solid #22c55e', borderRadius: 8, color: '#86efac', fontSize: 13 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontWeight: 600 }}>
                  <CheckCircle2 size={16} />
                  <span>{testResult.message} ({testResult.latency_ms}ms)</span>
                </div>
                {testResult.tables.length > 0 && (
                  <p style={{ margin: '6px 0 0', fontSize: 12, color: '#cbd5c7' }}>
                    Tables: {testResult.tables.slice(0, 8).join(', ')}{testResult.tables.length > 8 ? ` +${testResult.tables.length - 8} more` : ''}
                  </p>
                )}
              </div>
            )}

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 12, marginTop: 24 }}>
              <button
                type="button"
                className="reports-btn-secondary"
                onClick={handleTest}
                disabled={testing || saving}
                style={{ display: 'flex', alignItems: 'center', gap: 6 }}
              >
                {testing && <Loader2 size={14} className="spin" />}
                {testing ? 'Testing...' : 'Test Connection'}
              </button>
              <button
                type="button"
                className="reports-btn-primary"
                onClick={handleSave}
                disabled={saving || testing}
                style={{ background: '#c8fd39', color: '#101312', border: 'none', padding: '10px 20px', borderRadius: 8, fontWeight: 600, cursor: 'pointer' }}
              >
                {saving ? 'Saving...' : 'Save Connection'}
              </button>
            </div>
          </div>
        </div>
      )}

      <section className="analysis-hero">
        <div>
          <p className="eyebrow">EXPLORE WHAT IS CONNECTED</p>
          <h2>Understand your schema.</h2>
          <p>Browse tables, column types and relationships returned by the configured database.</p>
        </div>
        <Link className="editorial-link" to="/data-warehouse">Open data warehouse ↗</Link>
      </section>
    </div>
  );
}

