﻿import { useCallback, useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Database, MessageSquare, BarChart3 } from 'lucide-react';
import { datasetService } from '../../services/datasetService';
import { getStoredReports } from '../../services/reportsService';
import type { StoredReport } from '../../services/reportsService';
import type { Dataset } from '../../types/datasets';
export default function DashboardPage() {
 const navigate = useNavigate();
 const [datasets, setDatasets] = useState<Dataset[]>([]); const [reports, setReports] = useState<StoredReport[]>([]);
 const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [reportError, setReportError] = useState('');
 const [question, setQuestion] = useState('');
 const load = useCallback(async () => {
   setLoading(true); setError(''); setReportError('');
   const results = await Promise.allSettled([datasetService.list(0, 100), getStoredReports()]);
   if (results[0].status === 'fulfilled') setDatasets(results[0].value); else setError(results[0].reason instanceof Error ? results[0].reason.message : 'Unable to load datasets.');
   if (results[1].status === 'fulfilled') setReports(results[1].value); else setReportError(results[1].reason instanceof Error ? results[1].reason.message : 'Unable to load reports.');
   setLoading(false);
 }, []);
 useEffect(() => { void load(); }, [load]);
 const profiled = datasets.filter(d => d.quality_score != null);
 return <div className="ws-page dashboard-overview"><header className="editorial-heading"><p className="eyebrow">WORKSPACE / OVERVIEW</p><h1 className="ws-page-heading">Your data. A clearer view.</h1><p className="ws-page-sub">Move from raw information to questions worth exploring.</p></header>
 <div className="metric-strip"><Link className="metric-tile" to="/datasets"><span>Available datasets</span><strong>{loading || error ? '—' : `${datasets.length}${datasets.length === 100 ? '+' : ''}`}</strong><small>{datasets.length === 100 ? 'First 100 registry records loaded' : 'Dataset registry'}</small></Link><Link className="metric-tile" to="/reports"><span>Saved reports</span><strong>{loading || reportError ? '—' : reports.length}</strong><small>Returned report history</small></Link><Link className="metric-tile" to="/datasets"><span>Quality profiles</span><strong>{loading || error ? '—' : profiled.length}</strong><small>Loaded datasets with a quality score</small></Link></div>
 <form className="ws-composer" onSubmit={e => { e.preventDefault(); if (question.trim()) navigate('/analysis', { state: { question: question.trim() } }); }}><p className="eyebrow" style={{ color: '#c8fd39' }}>YOUR AI ANALYST</p><h2 style={{ color: '#fff' }}>What would you like to understand?</h2><label className="sr-only" htmlFor="dashboard-question">Analytical question</label><textarea id="dashboard-question" className="ws-composer-textarea" rows={2} value={question} onChange={e => setQuestion(e.target.value)} placeholder="Ask a question about your dataset" /><div className="ws-composer-footer"><button className="ws-composer-send" disabled={!question.trim()}>Open analysis ↗</button></div></form>
 <div className="ws-quick-grid">{[{ to: '/datasets/upload', icon: Database, title: 'Bring your data', description: 'Upload and profile a supported file.' }, { to: '/analysis', icon: MessageSquare, title: 'Ask a question', description: 'Inspect answers and their evidence.' }, { to: '/visualizations', icon: BarChart3, title: 'Find a perspective', description: 'Build charts from actual records.' }].map(action => <Link key={action.to} to={action.to} className="ws-quick-card"><action.icon size={20} /><h2 className="ws-quick-card-title">{action.title}</h2><p className="ws-quick-card-desc">{action.description}</p></Link>)}</div>
 <section className="ws-section-card"><div className="ws-section-card-header"><h2 className="ws-section-card-title">Dataset registry</h2><Link to="/datasets" className="ws-section-card-link">View all datasets →</Link></div>
 {loading ? <p className="ws-empty" role="status">Loading datasets…</p> : error ? <div className="ws-empty" role="alert"><p>{error}</p><button className="reports-btn-secondary" onClick={() => void load()}>Try again</button></div> : datasets.length ? <div className="ws-dataset-list">{datasets.slice(0, 5).map(ds => <Link key={ds.dataset_id} className="ws-dataset-item" to={'/datasets/' + encodeURIComponent(ds.dataset_id)}><Database size={18} /><div className="ws-dataset-info"><p className="ws-dataset-name">{ds.name}</p><p className="ws-dataset-meta">{(ds.row_count ?? 0).toLocaleString()} rows · {ds.column_count} columns</p></div><span className="ws-badge">{ds.status}</span></Link>)}</div> : <div className="ws-empty"><Database size={28} /><h3>No datasets uploaded yet.</h3><p>Upload a supported data file to begin.</p><Link className="reports-create-btn" to="/datasets/upload">Upload dataset</Link></div>}</section>
 <section className="ws-section-card"><div className="ws-section-card-header"><h2 className="ws-section-card-title">Recent reports</h2><Link className="ws-section-card-link" to="/reports">Open report library →</Link></div>{loading ? <p className="ws-empty" role="status">Loading reports…</p> : reportError ? <div className="ws-empty" role="alert"><p>{reportError}</p><button className="reports-btn-secondary" onClick={() => void load()}>Retry reports</button></div> : reports.length ? <div className="ws-dataset-list">{reports.slice(0, 4).map(r => <Link key={r.id} className="ws-dataset-item" to={'/reports/' + encodeURIComponent(r.id)}><div><p className="ws-dataset-name">{r.title}</p><p className="ws-dataset-meta">{r.report_type} · {new Date(r.created_at).toLocaleDateString()}</p></div></Link>)}</div> : <p className="ws-empty">No reports returned by the report library.</p>}</section>
 <p className="source-note">Activity totals and analysis counts are unavailable from the connected workspace APIs. Explore recent questions within your current analysis session.</p></div>;
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Download, LayoutDashboard, RefreshCw } from 'lucide-react';
import { apiClient } from '../../api/client';
import { useAuth } from '../../context/AuthContext';
import { downloadWorkbenchJson, workbenchService } from '../../services/workbenchService';
import type { SourceDataset } from '../../services/workbenchService';

interface DashboardSnapshot {
  id: string; title: string; created_at: string; dataset_id: string; sample_rows: number; total_rows: number | null;
  metric?: string; dimension?: string;
  kpis: { id: string; label: string; value: number }[];
  charts?: { id: string; type: string; title: string; points: { label: string; value: number; count?: number }[] }[];
}
const STORAGE_KEY = 'analyst.dashboard.snapshot.v1';
function readSnapshot(storageKey: string): DashboardSnapshot | null {
  try {
    const data = JSON.parse(localStorage.getItem(storageKey) ?? 'null');
    return data && typeof data.dataset_id === 'string' && Array.isArray(data.kpis) && data.kpis.every((k: { value: unknown }) => typeof k.value === 'number' && Number.isFinite(k.value)) ? data : null;
  } catch { return null; }
}
export default function DashboardStudioPage() {
  const { user } = useAuth();
  const storageKey = `${STORAGE_KEY}:${user?.id ?? 'anonymous'}`;
  const [snapshot, setSnapshot] = useState<DashboardSnapshot | null>(() => readSnapshot(storageKey));
  const [datasets, setDatasets] = useState<SourceDataset[]>([]);
  const [datasetId, setDatasetId] = useState('');
  const [title, setTitle] = useState('Dataset overview');
  const [busy, setBusy] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [revision, setRevision] = useState(0);
  const [layout, setLayout] = useState<'grid' | 'list'>('grid');
  useEffect(() => {
    let active = true;
    workbenchService.datasets().then(async data => {
      if (!active) return;
      setDatasets(data);
      // Attempt to load latest persisted dashboard from server
      try {
        const serverDashboards = await apiClient.get<any[]>('/api/v1/os/dashboards');
        if (active && Array.isArray(serverDashboards) && serverDashboards.length > 0) {
          const latest = serverDashboards[serverDashboards.length - 1];
          if (latest && Array.isArray(latest.kpis)) {
            const clean: DashboardSnapshot = {
              id: latest.id, title: latest.title, created_at: latest.created_at, dataset_id: latest.provenance?.dataset_id || latest.dataset_id || '',
              sample_rows: latest.filtered_rows ?? latest.population_size ?? 0, total_rows: latest.population_size ?? null,
              metric: latest.metric, dimension: latest.dimension,
              kpis: latest.kpis.filter((k: any) => Number.isFinite(k.value)).map(({ id, label, value }: any) => ({ id, label, value })),
              charts: latest.charts,
            };
            setSnapshot(clean);
          }
        }
      } catch {
        // Fallback to local state if server listing is empty
      }
    }).catch(e => { if (active) setError(e.message); }).finally(() => { if (active) setBusy(false); });
    return () => { active = false; };
  }, [revision]);
  async function generate() {
    if (!datasetId) return;
    setBusy(true); setError(''); setNotice('');
    try {
      const data = await apiClient.post<any>('/api/v1/os/dashboards/generate', {
        prompt: 'Summarize the supplied dataset',
        title: title.trim() || 'Dataset overview',
        dataset_id: datasetId,
      });
      if (!Array.isArray(data.kpis)) throw new Error('The dashboard service returned invalid metrics.');
      const clean: DashboardSnapshot = {
        id: data.id, title: data.title, created_at: data.created_at, dataset_id: datasetId,
        sample_rows: data.filtered_rows ?? data.population_size ?? 0, total_rows: data.population_size ?? null,
        metric: data.metric, dimension: data.dimension,
        kpis: data.kpis.filter((k: any) => Number.isFinite(k.value)).map(({ id, label, value }: any) => ({ id, label, value })),
        charts: data.charts,
      };
      setSnapshot(clean);
      try { localStorage.setItem(storageKey, JSON.stringify(clean)); setNotice('Dashboard persisted to server and local workspace.'); }
      catch { setNotice('Dashboard saved to server.'); }
    } catch (e) { setError(e instanceof Error ? e.message : 'Dashboard generation failed.'); }
    finally { setBusy(false); }
  }
  return <div className="page-container">
    <header className="page-header editorial-heading"><div><p className="eyebrow">WORKSPACE / DASHBOARD STUDIO</p><h1 className="page-title">Make room for the big picture.</h1><p className="page-subtitle">Build a saved summary from actual dataset records.</p></div>
      <button className="btn btn--ghost" disabled={!snapshot} onClick={() => downloadWorkbenchJson(snapshot, 'dashboard.json')}><Download size={15} /> Export JSON</button>
    </header>
    <div className="dashboard-studio-workspace">
    <form className="mem-panel workspace-inspector" onSubmit={e => { e.preventDefault(); void generate(); }}>
      <p className="eyebrow">YOUR BUILDING BLOCKS</p><h2>Configure your canvas</h2>
      <label className="fw-param">Dataset<select className="fw-select" disabled={busy} value={datasetId} onChange={e => setDatasetId(e.target.value)}><option value="">Select an uploaded dataset</option>{datasets.map(d => <option key={d.dataset_id} value={d.dataset_id}>{d.dataset_name}</option>)}</select></label>
      <label className="fw-param">Dashboard title<input className="fw-select" value={title} onChange={e => setTitle(e.target.value)} disabled={busy} maxLength={120} /></label>
      <button className="btn btn--primary" disabled={busy || !datasetId}><RefreshCw size={15} /> {busy ? 'Loading…' : 'Generate snapshot'}</button>
      <p className="page-subtitle">Calculated over full dataset population. All matching observations are computed directly from authoritative storage.</p>
    </form>
    <div className="dashboard-canvas" aria-busy={busy}>
    <div className="canvas-toolbar"><span className="eyebrow">LIVE WORKSPACE</span><label className="control-field">Card layout<select value={layout} onChange={e => setLayout(e.target.value as 'grid' | 'list')}><option value="grid">Grid</option><option value="list">Stacked</option></select></label></div>
    {error && <div role="alert" className="source-note"><p>{error}</p><button className="btn btn--ghost" disabled={busy} onClick={() => { setError(''); setBusy(true); setRevision(v => v + 1); }}>Retry dataset connection</button></div>}
    {notice && <p role="status">{notice}</p>}
    {busy && <p role="status">Waiting for the dataset or dashboard service…</p>}
    {!busy && !datasets.length && !error && <div className="mem-empty"><h2>No datasets uploaded yet.</h2><p>Upload a dataset to create your first dashboard.</p><Link className="btn btn--primary" to="/datasets">Open datasets</Link></div>}
    {snapshot && <section><h2>{snapshot.title}</h2><p className="page-subtitle">Persistent dashboard · {new Date(snapshot.created_at).toLocaleString()} · Dataset {snapshot.dataset_id} · {snapshot.sample_rows} computed of {snapshot.total_rows ?? snapshot.sample_rows} total rows</p><p className="page-subtitle">Full population metrics. Values use source units without artificial assumptions.</p>
      <div className={`snapshot-cards snapshot-cards--${layout}`}>{snapshot.kpis.map(k => <article className="ds-widget" key={k.id}><div className="ds-widget-body"><div className="ds-kpi-label">{k.label}</div><div className="ds-kpi-value">{k.value.toLocaleString(undefined, { maximumFractionDigits: 2 })}</div><p className="page-subtitle">Full Dataset</p></div></article>)}</div>
      {snapshot.charts && snapshot.charts.length > 0 && <div className="dashboard-charts-grid" style={{ marginTop: 24 }}>
        {snapshot.charts.map(chart => <div key={chart.id} className="ds-widget" style={{ padding: 16 }}>
          <h3 className="ds-kpi-label" style={{ marginBottom: 12 }}>{chart.title}</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {chart.points.slice(0, 10).map((pt, idx) => <div key={idx} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span style={{ fontSize: 13, color: '#A0A090' }}>{pt.label}</span>
              <strong style={{ fontSize: 14 }}>{pt.value != null ? pt.value.toLocaleString(undefined, { maximumFractionDigits: 2 }) : 'N/A'}</strong>
            </div>)}
          </div>
        </div>)}
      </div>}
    </section>}
    {!snapshot && !busy && datasets.length > 0 && <div className="mem-empty"><LayoutDashboard size={36} /><h2>No dashboard created yet</h2><p>Select a dataset to calculate its summary.</p></div>}
    </div></div>
  </div>;
}

