                  <span style={{ fontSize: 9, color: '#D6FA43', fontWeight: 600, letterSpacing: '0.08em' }}>SEASONALITY DETECTED</span>
                )}
              </div>
              <span className="eda-trend-rate">{t.growth_rate_pct >= 0 ? '+' : ''}{fmtPct(t.growth_rate_pct)}</span>
            </div>
          ))}
